import{_ as a,o as t,c as n,a3 as i}from"./chunks/framework.WFmvnizL.js";const g=JSON.parse('{"title":"Internationalization and bilingual docs","description":"Contribute Nezha translations with Dashboard gettext templates and compiled catalogs, frontend i18next resources, synchronized bilingual documentation, and verification.","frontmatter":{"description":"Contribute Nezha translations with Dashboard gettext templates and compiled catalogs, frontend i18next resources, synchronized bilingual documentation, and verification.","outline":"deep"},"headers":[],"relativePath":"en_US/developer/i18n.md","filePath":"en_US/developer/i18n.md","lastUpdated":1792850916000}'),s={name:"en_US/developer/i18n.md"};function o(r,e,d,l,c,h){return t(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="internationalization-and-bilingual-docs" tabindex="-1">Internationalization and bilingual docs <a class="header-anchor" href="#internationalization-and-bilingual-docs" aria-label="Permalink to &quot;Internationalization and bilingual docs&quot;">​</a></h1><p>Nezha has three independent resource sets: Dashboard Go messages, user/admin frontend UI, and documentation. Updating one does not automatically translate the others.</p><h2 id="contribute-through-weblate" tabindex="-1">Contribute through Weblate <a class="header-anchor" href="#contribute-through-weblate" aria-label="Permalink to &quot;Contribute through Weblate&quot;">​</a></h2><p>Prefer <a href="https://hosted.weblate.org/engage/nezha/" target="_blank" rel="noreferrer">Nezha Hosted Weblate</a> for routine translation to avoid conflicting with automatic synchronization. New source messages or languages still need repository integration.</p><h2 id="dashboard-gettext" tabindex="-1">Dashboard: gettext <a class="header-anchor" href="#dashboard-gettext" aria-label="Permalink to &quot;Dashboard: gettext&quot;">​</a></h2><p>Catalogs live under <code>pkg/i18n/translations/&lt;locale&gt;/LC_MESSAGES/nezha.po</code> and compiled <code>nezha.mo</code>; the template is <code>pkg/i18n/template.pot</code>. Use existing Localizer methods such as <code>T</code>, <code>Tf</code>, <code>ErrorT</code>, and <code>N</code>, rather than concatenating translatable sentences in handlers.</p><p>From the Dashboard root, with Bash 4+ and gettext tools available:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> script/i18n.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> generate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> template</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> script/i18n.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zh_CN</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> script/i18n.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zh_CN</span></span></code></pre></div><p>Extract source text, merge PO, complete/review translations, then compile MO. Edit/review PO between the last two commands. Changing PO alone does not update embedded MO; rebuild Dashboard after compilation. For a new locale, check actual catalog directories and language registration instead of copying a frontend&#39;s locale format.</p><p>Preserve format placeholders in <code>Tf</code>/<code>ErrorT</code> and the existing plural convention for <code>N</code>. Do not translate JSON keys, API paths, scopes, commands, or machine-read enum values.</p><h2 id="frontends-i18next" tabindex="-1">Frontends: i18next <a class="header-anchor" href="#frontends-i18next" aria-label="Permalink to &quot;Frontends: i18next&quot;">​</a></h2><p>Both frontends keep JSON in their own <code>src/locales</code>, but directories, registration, and keys may differ. User frontend initialization is <code>src/i18n.js</code>; admin initialization is <code>src/lib/i18n.ts</code>.</p><p>Update base-language and translated keys together, preserving interpolation names, plurals, and nesting. A new language needs resource import, code registration, and language-switcher verification, not just an extra JSON file.</p><p>Check long text, wrapping, date/number formatting, missing-key fallback, and retained state across language changes. Avoid fixed dimensions based on Chinese text width. Theme work also needs <a href="/en_US/developer/testing.html">frontend checks</a>.</p><h2 id="documentation-maintain-pairs" tabindex="-1">Documentation: maintain pairs <a class="header-anchor" href="#documentation-maintain-pairs" aria-label="Permalink to &quot;Documentation: maintain pairs&quot;">​</a></h2><p>Chinese <code>docs/&lt;section&gt;/&lt;page&gt;.md</code> pairs with English <code>docs/en_US/&lt;section&gt;/&lt;page&gt;.md</code>. For every feature update, verify:</p><ul><li>Matching titles, descriptions, defaults, constraints, and example semantics.</li><li>English internal links target <code>/en_US/</code> pages and actual translated anchors.</li><li>Both language sections in <code>docs/.vitepress/config.mts</code> stay synchronized.</li><li>Accurate page <code>description</code>; shared SEO generates canonical, hreflang, sitemap, and structured data.</li><li>Important entry points appear in <code>docs/public/llms.txt</code>; structured text never promises capabilities absent from visible content.</li></ul><p>Run <code>npm test</code> and <code>git diff --check</code> from the documentation root. Automated checks validate structure; manually review permissions, defaults, and negative statements to avoid reversing meaning in translation.</p>`,18)])])}const u=a(s,[["render",o]]);export{g as __pageData,u as default};
